/* global process */
import { SITE_URL, STATIC_PAGES } from '../src/seo/seoConfig.js';

/**
 * /sitemap.xml (rewritten here by vercel.json).
 *
 * The full sitemap is generated by the backend from the database. The backend may be cold
 * (Render), so: short timeout, CDN caching with a long stale-while-revalidate window, and a
 * static-pages-only fallback so crawlers never receive an error or an HTML page.
 */
const BACKEND_URL = (
  process.env.SITEMAP_BACKEND_URL ||
  process.env.VITE_BACKEND_URL ||
  'https://eventdecor-fg3l.onrender.com'
).replace(/\/+$/, '');

function fallbackSitemap() {
  const urls = Object.keys(STATIC_PAGES)
    .map(
      (path) =>
        `  <url>\n    <loc>${path === '/' ? `${SITE_URL}/` : `${SITE_URL}${path}`}</loc>\n  </url>`,
    )
    .join('\n');
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`;
}

export default async function handler(req, res) {
  res.setHeader('Content-Type', 'application/xml; charset=utf-8');
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    const response = await fetch(`${BACKEND_URL}/sitemap.xml`, { signal: controller.signal });
    clearTimeout(timer);
    const xml = await response.text();
    if (!response.ok || !xml.includes('<urlset'))
      throw new Error(`Backend sitemap ${response.status}`);
    res.setHeader(
      'Cache-Control',
      'public, max-age=0, s-maxage=3600, stale-while-revalidate=86400',
    );
    return res.status(200).send(xml);
  } catch (error) {
    console.error('Sitemap proxy error, serving static fallback:', error?.message || error);
    // Short cache so the full sitemap replaces this as soon as the backend is reachable.
    res.setHeader('Cache-Control', 'public, max-age=0, s-maxage=300');
    return res.status(200).send(fallbackSitemap());
  }
}
